/**
 * @file apply-talent-pools.mjs
 * @brief Rewrites the `talents` array of every entry of src/data/raw/species-data.js with the
 * completed pool of tools/data/talent-pools.mjs (rule in that file's header).
 *
 * The table is generated by gen-species.mjs, which now applies the same rule; this script exists
 * so the checked-in table can be repaired without the original repository at hand, and so the
 * repair can be verified (idempotence, no other change) by tests/TalentPools.test.js.
 *
 * Usage: node tools/data/apply-talent-pools.mjs           rewrite the table (idempotent)
 *        node tools/data/apply-talent-pools.mjs --check   report the pending changes, exit 1
 */

import fs from 'fs';
import path from 'path';
import { PROJECT_ROOT, inline } from './TableWriter.mjs';
import { completeTalentPool } from './talent-pools.mjs';
import { SPECIES_TABLE } from '../../src/data/raw/species-data.js';

const FILE = 'src/data/raw/species-data.js';
const ENTRY_START = /^ {2}("[^"]+"|[A-Za-z0-9_$]+): \{/;
const TALENT_LIST = /talents: \[[^\]]*\],/;

const target = path.join(PROJECT_ROOT, FILE);
const source = fs.readFileSync(target, 'utf8');
const lines = source.split('\n');
const changes = [];
let seen = 0;

for (let index = 0; index < lines.length; index++) {
  const start = ENTRY_START.exec(lines[index]);
  if (!start) continue;
  const id = start[1].replace(/^"|"$/g, "");
  const species = SPECIES_TABLE[id];
  if (!species) throw new Error(`species-data.js entry without data: ${id}`);
  if (!TALENT_LIST.test(lines[index])) throw new Error(`no talent list on the line of ${id}`);
  seen++;
  const completed = completeTalentPool(species.types, species.talents);
  const next = lines[index].replace(TALENT_LIST, `talents: ${inline(completed)},`);
  if (next !== lines[index]) {
    changes.push(`${id} (${species.talents.length} -> ${completed.length})`);
    lines[index] = next;
  }
}

const known = Object.keys(SPECIES_TABLE).length;
if (seen !== known) throw new Error(`${seen} entries rewritten for ${known} species in the table`);

const check = process.argv.includes('--check');
if (check) {
  if (changes.length > 0) {
    console.error(`${changes.length} species still have an incomplete talent pool: ${changes.slice(0, 10).join(', ')}`);
    process.exit(1);
  }
  console.log(`talent pools complete: ${known} species`);
} else if (changes.length === 0) {
  console.log(`talent pools already complete: ${known} species, nothing written`);
} else {
  fs.writeFileSync(target, lines.join('\n'));
  console.log(`${changes.length} talent pools completed out of ${known} species`);
}
